// ---------- Settings ----------
const GHL_LOCATION_ID = 'YOUR_GHL_LOCATION_ID';
const GHL_ASSIGNED_USER_ID = '';   // optional: GHL user id that owns follow-up tasks
const FOLLOW_UP_PLAN = {
  hot:  [ { days: 1,  title: 'Call {name} – talk numbers on {property}' },
          { days: 3,  title: 'Book second visit / paperwork for {name}' } ],
  warm: [ { days: 2,  title: 'Check in with {name} after {property} visit' },
          { days: 7,  title: 'Send {name} new options and ask for feedback' } ],
  cold: [ { days: 7,  title: 'Light touch: new listings for {name}' },
          { days: 21, title: 'Re-engage {name} – has anything changed?' } ]
};
// ------------------------------

const raw = $input.first().json;
let ai = raw.message?.content ?? raw.content ?? {};
if (typeof ai === 'string') {
  try { ai = JSON.parse(ai.replace(/```json|```/g, '').trim()); } catch (e) { ai = {}; }
}

const tg = $('Agent Voice Note').first().json.message;
const name = (ai.buyer_name || 'Buyer').trim();
const [firstName, ...rest] = name.split(/\s+/);
const level = ['hot', 'warm', 'cold'].includes(ai.interest_level) ? ai.interest_level : 'warm';
const phone = String(ai.buyer_phone || '').replace(/[^\d+]/g, '');
const email = String(ai.buyer_email || '').trim().toLowerCase();
const property = ai.property_visited || ai.listing_id || 'the property';
const list = v => Array.isArray(v) ? v.filter(Boolean) : [];

const now = new Date();
const followUps = (FOLLOW_UP_PLAN[level] || []).map(step => {
  const due = new Date(now.getTime() + step.days * 24 * 60 * 60 * 1000);
  due.setHours(10, 0, 0, 0);
  return {
    title: step.title.replace('{name}', firstName).replace('{property}', property),
    body: `Interest: ${level} (${ai.interest_score || '?'}/10). Concerns: ${list(ai.concerns).join(', ') || 'none noted'}. Buyer said next: ${ai.buyer_next_step || '—'}`,
    dueDate: due.toISOString(),
    ...(GHL_ASSIGNED_USER_ID ? { assignedTo: GHL_ASSIGNED_USER_ID } : {})
  };
});

const noteText = [
  `Site visit – ${property} (${now.toISOString().slice(0, 10)})`,
  `Agent: ${tg.from?.first_name || 'Agent'}`,
  `Interest: ${level.toUpperCase()} – ${ai.interest_score || '?'}/10`,
  `Summary: ${ai.summary || ''}`,
  `Liked: ${list(ai.liked).join(', ') || '—'}`,
  `Concerns: ${list(ai.concerns).join(', ') || '—'}`,
  `Budget: ${ai.budget_max || 'not given'} | Areas: ${list(ai.preferred_areas).join(', ') || '—'} | Beds: ${ai.bedrooms || '—'} | Type: ${ai.property_type || '—'}`,
  `Buyer's next step: ${ai.buyer_next_step || '—'}`
].join('\n');

return [{
  json: {
    ghl_location_id: GHL_LOCATION_ID,
    agent_chat_id: tg.chat.id,
    buyer_name: name,
    first_name: firstName,
    last_name: rest.join(' '),
    buyer_phone: phone,
    buyer_email: email,
    has_contact: Boolean(phone || email),
    property_visited: property,
    listing_id: ai.listing_id || '',
    interest_level: level,
    interest_score: Number(ai.interest_score) || 0,
    budget_max: Number(ai.budget_max) || 0,
    preferred_areas: list(ai.preferred_areas),
    bedrooms: Number(ai.bedrooms) || 0,
    property_type: ai.property_type || '',
    liked: list(ai.liked),
    concerns: list(ai.concerns),
    tags: ['site-visit', `interest-${level}`],
    note_text: noteText,
    follow_ups: followUps
  }
}];

// Score available listings against what the buyer wants and keep the top 3.
const visit = $('Build Visit Record').first().json;
const contactId = $('Upsert Buyer in GHL').first().json.contact?.id || '';
const norm = s => String(s ?? '').trim().toLowerCase();
const num = v => Number(String(v ?? '').replace(/[^0-9.]/g, '')) || 0;
const areas = visit.preferred_areas.map(norm);

const scored = $input.all().map(i => i.json)
  .filter(l => ['available', ''].includes(norm(l.status)))
  .filter(l => norm(l.listing_id) !== norm(visit.listing_id) || !visit.listing_id)
  .filter(l => norm(l.title) !== norm(visit.property_visited))
  .map(l => {
    let score = 0;
    const price = num(l.price);
    if (areas.length && areas.some(a => norm(l.area).includes(a) || a.includes(norm(l.area)))) score += 3;
    if (visit.budget_max && price) {
      if (price <= visit.budget_max * 1.05) score += 3;
      else if (price <= visit.budget_max * 1.15) score += 1;
      else score -= 4;
    }
    const beds = num(l.bedrooms);
    if (visit.bedrooms && beds) score += beds === visit.bedrooms ? 2 : Math.abs(beds - visit.bedrooms) === 1 ? 1 : 0;
    if (visit.property_type && norm(l.property_type) === norm(visit.property_type)) score += 2;
    return { ...l, score };
  })
  .filter(l => l.score >= 3)
  .sort((a, b) => b.score - a.score)
  .slice(0, 3);

const likedLine = visit.liked.length ? ` Since you liked ${visit.liked.slice(0, 3).join(', ')}, these might be worth a look:` : ' Here are a few similar homes you might like:';
const items = scored.map(l =>
  `<li><b>${l.title}</b> – ${l.area}, ${l.bedrooms || '?'} bed, ${l.price}${l.url ? ` · <a href="${l.url}">View details</a>` : ''}</li>`
).join('');
const emailHtml = `<p>Hi ${visit.first_name},</p>
<p>Thanks for visiting ${visit.property_visited} today.${likedLine}</p>
<ul>${items}</ul>
<p>Reply here if you'd like to see any of them and I'll set up a visit.</p>`;

return [{
  json: {
    ...visit,
    contact_id: contactId,
    matches: scored.map(l => ({ listing_id: l.listing_id, title: l.title, area: l.area, price: l.price, url: l.url })),
    email_html: emailHtml,
    follow_ups: visit.follow_ups.map(f => ({ ...f, contact_id: contactId }))
  }
}];

